final class Account {
  private val gate = new Object            // published lock
  private var balance: Long = 0
  def lock: AnyRef = gate

  def transferTo(to: Account, amount: Long): Unit =
    gate.synchronized {                    // exclusive lock on the gate
      to.lock.synchronized { balance -= amount; to.add(amount) }
    }
  def add(amount: Long): Unit = balance += amount   // caller holds the lock
}
